def main():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])

    fits = []
    if -32768 <= n <= 32767:
        fits.append("Fits in short int")
    if -2147483648 <= n <= 2147483647:
        fits.append("Fits in long int")
    if 0 <= n <= 65535:
        fits.append("Fits in unsigned short int")
    if 0 <= n <= 4294967295:
        fits.append("Fits in unsigned long int")

    if not fits:
        fits.append("Does not fit in any type")
    else:
        fits.append("Does not fit in any type")

    print("\n".join(fits))

